def app_icon_svg_markup(size: int = 48) -> str:
    """Embedded app icon SVG scaled for HTML headers (no external file)."""
    sz = max(16, int(size))
    out = APP_ICON_SVG
    out = re.sub(r'\bwidth="\d+"', f'width="{sz}"', out, count=1)
    out = re.sub(r'\bheight="\d+"', f'height="{sz}"', out, count=1)
    return out


