                f"<section class=\"report-card\"><h2>Execution Time Per Slice{_esc(scope_title)}</h2>"
                "<table><thead><tr><th>Task</th><th>Runs</th><th>CPU%</th>"
                "<th>Min</th><th>Avg</th><th>TrimMean(5%)</th><th>Max</th>"
