                tb_disabled   = "#555555",
                status_text   = "#AAAAAA",
                cb_border     = "#555555",
                cb_bg         = "#2D2D2D",
                input_bg      = "#2D2D2D",
                input_fg      = "#D4D4D4",
                input_border  = "#555555",
